// AUTORESEARCH: regenerated by experiment.py from agent/prompts/, agent/weights.json and test_jobs/.
// The copy in this repo is the empty baseline on purpose -- an empty test_jobs
// array means a deploy can never spend LLM time by accident.
const CONFIG = { experiment_id: 'unset', model: 'qwen2.5:7b', prompt: '', weights: {}, test_jobs: [] };
return [{ json: CONFIG }];

// Applies agent/weights.json deterministically instead of trusting the
// LLM's own overall_score, so weight tuning is a real lever.
const cfg = $('Experiment Config').first().json;
const src = $('Load Test Set').item.json;
let txt = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
txt = txt.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let r = {};
try { r = JSON.parse(txt); } catch (e) { r = { parse_error: String(e && e.message) }; }
const num = (v) => Math.max(0, Math.min(100, Number(v) || 0));
const w = cfg.weights || {};
const role = num(r.role_match);
const skill = num(r.skill_match);
const location = num(r.location_match);
const tweak = num(r.tweak_level);
let overall = role * (w.role_weight || 0) + skill * (w.skill_weight || 0) + location * (w.location_weight || 0) + (100 - tweak) * (w.tweak_weight || 0);

// The gate is arithmetic on the LOW number of the stated range: a job ad
// states the minimum the employer will ACCEPT, so "0-3 years" accepts a
// 3-year candidate. Reading the high bound (or requiring min > 3) throws away
// good jobs -- that inversion gated out 4 of 100 real jobs in prod.
// `experience` is empty on 0/28 real jobs, so read the JD text too.
const blob = (String((src.job || {}).experience || '') + ' ' + String((src.job || {}).jd || '')).slice(0, 2000);
const years = blob.match(/(\d{1,2})\s*(?:-|to|\u2013|\u2014)\s*(\d{1,2})\s*(?:years?|yrs?)|\b(\d{1,2})\s*\+?\s*(?:years?|yrs?)\b/i);
let gate;
if (years) {
  const lo = parseInt(years[1] || years[3], 10);
  gate = lo > 4 ? 'REJECT' : (lo > 3 ? 'REVIEW' : 'PASS');
} else {
  // No stated experience is not a disqualifier: 92% of real postings say
  // nothing, and rejecting them empties the pipeline. A senior/lead title is
  // not evidence either -- the candidate IS a "Lead Mobile App Developer".
  gate = 'MISSING_DATA';
}
if (gate === 'REJECT') { overall = -1; }
return { json: { experiment_id: cfg.experiment_id, company: src.job.company || '', title: src.job.title || '', experience_status: gate, experience_reason: r.experience_reason || '', role_match: role, skill_match: skill, location_match: location, tweak_level: tweak, overall_score: Math.round(overall * 100) / 100, recommended: gate !== 'REJECT' && role >= 50 && skill >= 60 && location >= 30, matched_skills: r.matched_skills || [], missing_skills: r.missing_skills || [], why_this_job: r.why_this_job || '', parse_error: r.parse_error || '', expected: src.expected } };
